	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.V1PublicGetPublicSystemInfo(params))
	PanicOnError(response)

	//
	//     {
	//         "success": true,
	//         "data": {
	//             "status": 0,
	//             "msg": "System is functioning properly."
	//         },
	//         "timestamp": "1709274106602"
