		var triggerPrice *string = this.SafeString2(orderParams, "triggerPrice", "stopPrice")
		var stopLoss any = this.SafeValue(orderParams, "stopLoss")
		var takeProfit any = this.SafeValue(orderParams, "takeProfit")
